import{_ as e,c as r,o as h,af as i}from"./chunks/framework.BKeRpnBD.js";const b=JSON.parse('{"title":"巽","description":"周易集解 - 巽","frontmatter":{"title":"巽","description":"周易集解 - 巽"},"headers":[],"relativePath":"classics/jijie/057.md","filePath":"classics/jijie/057.md"}'),l={name:"classics/jijie/057.md"};function n(d,a,p,t,s,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="巽" tabindex="-1">巽 <a class="header-anchor" href="#巽" aria-label="Permalink to “巽”">​</a></h1><h2 id="巽-1" tabindex="-1">巽 <a class="header-anchor" href="#巽-1" aria-label="Permalink to “巽”">​</a></h2><h2 id="卦辭" tabindex="-1">卦辭 <a class="header-anchor" href="#卦辭" aria-label="Permalink to “卦辭”">​</a></h2><p>巽，小亨，利有攸往，利見大人。</p><h2 id="卦辭注" tabindex="-1">卦辭注 <a class="header-anchor" href="#卦辭注" aria-label="Permalink to “卦辭注”">​</a></h2><p>《序卦》曰：旅而無所容，故受之以巽。巽者，入也。</p><p>崔憬曰：旅寄於外，而無所容，則必入矣。故曰：｢旅無所容，受之以巽。｣</p><p>虞翻曰：遯二之四，柔得位而順五剛，故小亨也。大人謂五。離目為見。二失位，利在往應五，故｢利有攸往，利見大人｣矣。</p><h2 id="彖" tabindex="-1">彖 <a class="header-anchor" href="#彖" aria-label="Permalink to “彖”">​</a></h2><p>《《彖》曰：重巽以申命，剛巽乎中正而志行，柔皆順乎剛，是以小亨。利有攸往，利見大人。</p><h2 id="彖傳注" tabindex="-1">彖傳注 <a class="header-anchor" href="#彖傳注" aria-label="Permalink to “彖傳注”">​</a></h2><p>陸績曰：巽為命令。重命令者，欲丁寧也。</p><p>陸績曰：二得中，五得正，體兩巽，故曰剛巽乎中正也。皆據陰，故志行也。</p><p>虞翻曰：剛中正，謂五也。二失位，動成坎，坎為志。終變成震，震為行也。</p><p>陸績曰：陰為卦主，故小亨。</p><p>案：其義已見繇辭。</p><h2 id="象" tabindex="-1">象 <a class="header-anchor" href="#象" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：隨風，巽。君子以申命行事。</p><h2 id="象傳注" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注" aria-label="Permalink to “象傳注”">​</a></h2><p>虞翻曰：君子，謂遯乾也。巽為命，重象，故申命。變至三，坤為事，震為行，故行事也。</p><p>荀爽曰：巽為號令，兩巽相隨，故申命也。法教百端，令行為上，貴其必從，故曰行事也。</p><h2 id="初六" tabindex="-1">初六 <a class="header-anchor" href="#初六" aria-label="Permalink to “初六”">​</a></h2><p>初六，進退，利武人之貞。</p><h2 id="初六注" tabindex="-1">初六注 <a class="header-anchor" href="#初六注" aria-label="Permalink to “初六注”">​</a></h2><p>虞翻曰：巽為進退。乾為武人。初失位，利之正為乾，故利武人之貞矣。</p><h2 id="象-1" tabindex="-1">象 <a class="header-anchor" href="#象-1" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：進退，志疑也。利武人之貞，志治也。</p><h2 id="象傳注-1" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-1" aria-label="Permalink to “象傳注”">​</a></h2><p>荀爽曰：風性動，進退欲承五，為二所據，故志以疑也。</p><p>虞翻曰：動而成乾，乾為大明，故志治。乾元用九，天下治，是其義也。</p><h2 id="九二" tabindex="-1">九二 <a class="header-anchor" href="#九二" aria-label="Permalink to “九二”">​</a></h2><p>九二，巽在床下，用史巫紛若，吉，無咎。</p><h2 id="九二注" tabindex="-1">九二注 <a class="header-anchor" href="#九二注" aria-label="Permalink to “九二注”">​</a></h2><p>宋衷曰：巽為木。二陽在上，初陰在下，床之象也。二無應於上，退而據初，心在於下，故曰巽在床下也。</p><p>荀爽曰：床下，以喻近也。二者，軍帥。三者，號令。故言床下。以明將之所專，不過軍中事也。</p><p>荀爽曰：史以書勳，巫以告廟。紛，變。若，順也。謂二以陽應陽，君所不臣，軍師之象。征伐既畢，書勳告廟。當變而且順五則吉。故曰｢用史巫紛若，吉無咎｣矣。</p><h2 id="象-2" tabindex="-1">象 <a class="header-anchor" href="#象-2" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：紛若之吉，得中也。</p><h2 id="象傳注-2" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-2" aria-label="Permalink to “象傳注”">​</a></h2><p>荀爽曰：謂二以處中和，故能變。</p><h2 id="九三" tabindex="-1">九三 <a class="header-anchor" href="#九三" aria-label="Permalink to “九三”">​</a></h2><p>九三，頻巽，吝。</p><h2 id="九三注" tabindex="-1">九三注 <a class="header-anchor" href="#九三注" aria-label="Permalink to “九三注”">​</a></h2><p>虞翻曰：頻，頞也。謂二已變。三體坎艮，坎為憂，艮為鼻，故頻巽。無應在險，故吝也。</p><h2 id="象-3" tabindex="-1">象 <a class="header-anchor" href="#象-3" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：頻巽之吝，志窮也。</p><h2 id="象傳注-3" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-3" aria-label="Permalink to “象傳注”">​</a></h2><p>荀爽曰：乘陽無據，為陰所乘，號令不行，故志窮也。</p><h2 id="六四" tabindex="-1">六四 <a class="header-anchor" href="#六四" aria-label="Permalink to “六四”">​</a></h2><p>六四，悔亡，田獲三品。</p><h2 id="六四注" tabindex="-1">六四注 <a class="header-anchor" href="#六四注" aria-label="Permalink to “六四注”">​</a></h2><p>虞翻曰：田，謂二也。地中稱田，失位無應，悔也。欲二之初，已得應之，故悔亡。二動得正，處中應五。五多功，故《象》曰｢有功也｣。二動艮為手，故稱獲。謂艮為狼，坎為豕。艮二之初，離為雉。故獲三品矣。</p><p>翟玄曰：田獲三品，下三爻也，謂初巽為雞，二兌為羊，三離為雉也。</p><p>案：《穀梁傳》曰：春獵曰田，夏曰苗，秋曰蒐，冬曰狩。田獲三品：一為乾豆，二為賓客，三為充君之庖。註雲：上殺中心，乾之為豆實；次殺中髀骼，以供賓客；下殺中腹，充君之庖廚。尊神敬客之義也。</p><h2 id="象-4" tabindex="-1">象 <a class="header-anchor" href="#象-4" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：田獲三品，有功也。</p><h2 id="象傳注-4" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-4" aria-label="Permalink to “象傳注”">​</a></h2><p>王弼曰：得位承五而依尊履正。以斯行命，必能獲強暴，遠不仁者也。獲而有益，莫若三品，故曰有功也。</p><h2 id="九五" tabindex="-1">九五 <a class="header-anchor" href="#九五" aria-label="Permalink to “九五”">​</a></h2><p>九五，貞吉，悔亡，無不利，無初有終。先庚三日，後庚三日，吉。</p><h2 id="九五注" tabindex="-1">九五注 <a class="header-anchor" href="#九五注" aria-label="Permalink to “九五注”">​</a></h2><p>虞翻曰：得位處中，故｢貞吉，悔亡，無不利｣也。震巽相薄，雷風無形，當變之震矣。巽究為躁卦，故無初有終也。</p><p>虞翻曰：震，庚也。謂變初至二成離，至三成震，震主庚。離為日，震三爻在前，故先庚三日。謂益時也。動四至五成離，終上成震，震三爻在後，故後庚三日也。巽初失正，終變成震，得位，故無初有終，吉。震究為蕃鮮，白，謂巽也。巽究為躁卦。躁卦，謂震也。與蠱｢先甲三日，後甲三日｣同義。五動成蠱，乾成於甲，震成於庚，陰陽天地之始終，故經舉甲庚於《蠱．彖》、巽五也。</p><h2 id="象-5" tabindex="-1">象 <a class="header-anchor" href="#象-5" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：九五之吉，位正中也。</p><h2 id="象傳注-5" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-5" aria-label="Permalink to “象傳注”">​</a></h2><p>虞翻曰：居中得正，故吉矣。</p><h2 id="上九" tabindex="-1">上九 <a class="header-anchor" href="#上九" aria-label="Permalink to “上九”">​</a></h2><p>《上九，巽在床下，喪其資斧，貞兇。</p><h2 id="上九注" tabindex="-1">上九注 <a class="header-anchor" href="#上九注" aria-label="Permalink to “上九注”">​</a></h2><p>虞翻曰：床下，為初也。窮上反下成震，故巽在床下。《象》曰｢上窮也｣。明當變窮上而復初也。</p><p>《九家易》曰：上為宗廟。禮封賞出軍，皆先告廟，然後受行。三軍之命，將之所專。故曰巽在床下也。</p><p>虞翻曰：變至三時，離毀入坤。坤為喪，離為斧，故喪其資斧。三變失位故貞兇。</p><p>荀爽曰：軍罷師旋，亦告於廟，還斧於君，故喪資斧。正如其故，不執臣節，則兇。故曰｢喪其資斧，貞兇｣。</p><h2 id="象-6" tabindex="-1">象 <a class="header-anchor" href="#象-6" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：巽在床下，上窮也。喪其資斧，正乎兇也。</p><h2 id="象傳注-6" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-6" aria-label="Permalink to “象傳注”">​</a></h2><p>虞翻曰：陽窮上反下，故曰上窮也。</p><p>虞翻曰：上應於三，三動失正，故曰正乎兇也。</p>',79)])])}const f=e(l,[["render",n]]);export{b as __pageData,f as default};
